umb">Workspace <span>/</span> Overview</div><div class="top-actions"><span class="role-chip"><?=e($roleName)?></span><div class="user-avatar" aria-hidden="true"><?=e(strtoupper(substr($_SESSION['name'] ?? 'U',0,1)))?></div><div class="user-name"><?=e($_SESSION['name'] ?? 'User')?></div></div></header><div class="page-content"><section class="welcome-row"><div><div class="eyebrow">YOUR SCHOOL NETWORK</div><h1>Good day, <?=e(explode(' ', trim($_SESSION['name'] ?? 'there'))[0])?>.</h1><p class="muted">Here’s the latest across your workspace.</p></div><?php if (can_manage_schools()): ?><a class="button primary" href="#schools">View schools <span aria-hidden="true">→</span></a><?php endif; ?></section><?php if (can_manage_schools()): ?><section class="metric-grid" aria-label="School overview"><article class="metric-card"><div class="metric-label">SCHOOLS IN NETWORK</div><div class="metric-value"><?=count($schools)?></div><div class="metric-note">Registered schools</div><span class="metric-symbol mint" aria-hidden="true">▦</span></article><article class="metric-card"><div class="metric-label">YOUR ROLE</div><div class="metric-value metric-role"><?=e($roleName)?></div><div class="metric-note">Access level</div><span class="metric-symbol lilac" aria-hidden="true">◇</span></article><article class="metric-card"><div class="metric-label">WORKSPACE</div><div class="metric-value metric-role">ShuleLite</div><div class="metric-note">School operations</div><span class="metric-symbol peach" aria-hidden="true">✳</span></article></section><?php endif; ?><section class="content-section" id="schools"><div class="section-heading"><div><div class="eyebrow">NETWORK</div><h2>Schools</h2></div><?php if (can_manage_schools()): ?><span class="count-pill"><?=count($schools)?> schools</span><?php endif; ?></div><?php if (!can_manage_schools()): ?><div class="empty-state"><span class="empty-icon" aria-hidden="true">⌂</span><h3>Your workspace is ready</h3><p>Your school information and tasks will 